package net.minecraft.resources;
public final class Identifier { final String text; private Identifier(String t){text=t;} public static Identifier parse(String t){return new Identifier(t);} public String getNamespace(){int i=text.indexOf(':');return i<0?"minecraft":text.substring(0,i);} public String getPath(){int i=text.indexOf(':');return i<0?text:text.substring(i+1);} public Identifier withPath(String p){return new Identifier(getNamespace()+":"+p);} public static Identifier withDefaultNamespace(String p){return new Identifier("minecraft:"+p);} public String toString(){return text;} public boolean equals(Object o){return o instanceof Identifier i&&text.equals(i.text);} public int hashCode(){return text.hashCode();} }
